CREATE TABLE "managed_documents" ("id" UUID NOT NULL,"type" VARCHAR(80) NOT NULL,"title" VARCHAR(255) NOT NULL,"classification" VARCHAR(80) NOT NULL,"status" VARCHAR(40) NOT NULL DEFAULT 'DRAFT',"ownerId" UUID NOT NULL,"createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdBy" UUID NOT NULL,"updatedAt" TIMESTAMPTZ(6) NOT NULL,"updatedBy" UUID NOT NULL,CONSTRAINT "managed_documents_pkey" PRIMARY KEY("id"));
CREATE TABLE "managed_document_versions" ("id" UUID NOT NULL,"documentId" UUID NOT NULL,"version" INTEGER NOT NULL,"uri" VARCHAR(1000) NOT NULL,"fileHash" CHAR(64) NOT NULL,"mimeType" VARCHAR(160) NOT NULL,"sizeBytes" BIGINT NOT NULL,"origin" VARCHAR(500) NOT NULL,"createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdBy" UUID NOT NULL,CONSTRAINT "managed_document_versions_pkey" PRIMARY KEY("id"),CONSTRAINT "managed_document_versions_size_positive" CHECK ("sizeBytes">0),CONSTRAINT "managed_document_versions_hash_sha256" CHECK ("fileHash"~'^[a-f0-9]{64}$'));
CREATE TABLE "managed_document_links" ("id" UUID NOT NULL,"documentId" UUID NOT NULL,"entityType" VARCHAR(80) NOT NULL,"entityId" VARCHAR(160) NOT NULL,"role" VARCHAR(80) NOT NULL,"createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdBy" UUID NOT NULL,CONSTRAINT "managed_document_links_pkey" PRIMARY KEY("id"));
CREATE INDEX "managed_documents_type_status_idx" ON "managed_documents"("type","status");CREATE INDEX "managed_documents_ownerId_status_idx" ON "managed_documents"("ownerId","status");
CREATE UNIQUE INDEX "managed_document_versions_documentId_version_key" ON "managed_document_versions"("documentId","version");CREATE UNIQUE INDEX "managed_document_versions_documentId_fileHash_key" ON "managed_document_versions"("documentId","fileHash");CREATE INDEX "managed_document_versions_fileHash_idx" ON "managed_document_versions"("fileHash");
CREATE UNIQUE INDEX "managed_document_links_documentId_entityType_entityId_role_key" ON "managed_document_links"("documentId","entityType","entityId","role");CREATE INDEX "managed_document_links_entityType_entityId_idx" ON "managed_document_links"("entityType","entityId");
ALTER TABLE "managed_documents" ADD CONSTRAINT "managed_documents_ownerId_fkey" FOREIGN KEY("ownerId") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "managed_document_versions" ADD CONSTRAINT "managed_document_versions_documentId_fkey" FOREIGN KEY("documentId") REFERENCES "managed_documents"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "managed_document_links" ADD CONSTRAINT "managed_document_links_documentId_fkey" FOREIGN KEY("documentId") REFERENCES "managed_documents"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE OR REPLACE FUNCTION prevent_managed_document_evidence_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'managed document evidence is append-only'; END; $$;CREATE TRIGGER managed_document_versions_append_only BEFORE UPDATE OR DELETE ON "managed_document_versions" FOR EACH ROW EXECUTE FUNCTION prevent_managed_document_evidence_mutation();CREATE TRIGGER managed_document_links_append_only BEFORE UPDATE OR DELETE ON "managed_document_links" FOR EACH ROW EXECUTE FUNCTION prevent_managed_document_evidence_mutation();
